
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mcml_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mcml", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.491729122808216e+00, -4.407219339446668e+00, -4.288817496749889e+00, -4.124825273720367e+00, -3.901379797110308e+00, -3.603915841366410e+00, -3.220605065699031e+00, -2.748699876477096e+00, -2.206726980793292e+00, -1.590824407442631e+00, -9.889191898808267e-01, -6.851131722971617e-01, -6.058517153261191e-01, -5.155384932068912e-01, -3.694574488777015e-01, -2.216795071232157e-01, -9.338581115271521e-02, -2.023076182338134e-02, -3.686502168532393e-03, -4.096393048265258e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


